INSERT INTO Actualites (aid, date_actualite, intitule, image, amorce, actualite, visible) VALUES (1, '2023-12-20', 'Semaine de sensibilisation à la lutte contre la faim', 'images/iconeArticle/iconeArticle.png', 'Semaine de sensibilisation à la lutte contre la faim', 'Participez à notre semaine de sensibilisation et d''action contre la faim se déroulant le 23/12/2023 à Molenbeek. Ensemble, nous pouvons créer un monde où personne ne souffre de la faim.', 1);
INSERT INTO Actualites (aid, date_actualite, intitule, image, amorce, actualite, visible) VALUES (2, '2023-12-20', 'Projet de construction de logements abordables', 'images/iconeArticle/iconeArticle.png', 'Projet de construction de logements abordables', 'Nous débutons un nouveau projet de construction de logements abordables pour offrir un toit à ceux qui en ont le plus besoin. Chacun mérite un foyer sûr.', 1);
INSERT INTO Actualites (aid, date_actualite, intitule, image, amorce, actualite, visible) VALUES (3, '2023-12-20', 'Soutien aux réfugiés : collecte de fournitures essentielles', 'images/iconeArticle/iconeArticle.png', 'Soutien aux réfugiés : collecte de fournitures essentielles', 'Joignez-vous à notre effort de soutien aux réfugiés en participant à notre collecte de fournitures
INSERT INTO Actualites (aid, date_actualite, intitule, image, amorce, actualite, visible) VALUES (4, '2023-12-20', 'Initiative de recyclage pour réduire notre empreinte carbone', 'images/iconeArticle/iconeArticle.png', 'Initiative de recyclage pour réduire notre empreinte carbone', 'Contribuons à un avenir durable ! Unis pour aider lance une initiative de recyclage pour réduire notre empreinte carbone et protéger notre planète.', 1);
INSERT INTO Actualites (aid, date_actualite, intitule, image, amorce, actualite, visible) VALUES (5, '2023-12-20', 'Événement de sensibilisation à la santé mentale', 'images/iconeArticle/iconeArticle.png', 'Événement de sensibilisation à la santé mentale', 'La santé mentale est une priorité. Unis pour aider organise un événement de sensibilisation pour éduquer et éliminer les stigmates liés à la santé mentale.', 1);
INSERT INTO Actualites (aid, date_actualite, intitule, image, amorce, actualite, visible) VALUES (6, '2023-12-20', 'Collecte de vêtements d''hiver pour les familles dans le besoin', 'images/iconeArticle/iconeArticle.png', 'Collecte de vêtements d''hiver pour les familles dans le besoin', 'Aidez-nous à collecter des vêtements d''hiver pour les familles défavorisées. Donnez de la chaleur à ceux qui en ont le plus besoin.', 1);
INSERT INTO Actualites (aid, date_actualite, intitule, image, amorce, actualite, visible) VALUES (7, '2023-12-20', 'Cours de secourisme gratuits ouverts à la communauté', 'images/iconeArticle/iconeArticle.png', 'Cours de secourisme gratuits ouverts à la communauté', 'Unis pour aider organise des cours de secourisme gratuits pour permettre à la communauté de développer des compétences essentielles en cas d''urgence.', 1);
