INSERT INTO Actualites (aid, date_actualite, intitule, image, amorce, actualite, visible) VALUES (9, '2023-12-21', 'Soutien psychologique pour les victimes de traumatismes', 'images/iconeArticle/iconeArticle.png', 'Soutien psychologique pour les victimes de traumatismes', 'Notre équipe de professionnels de la santé mentale offre un soutien psychologique aux personnes
INSERT INTO Actualites (aid, date_actualite, intitule, image, amorce, actualite, visible) VALUES (10, '2023-12-21', 'Projet de plantation d''arbres pour un environnement plus vert', 'images/iconeArticle/iconeArticle.png', 'Projet de plantation d''arbres pour un environnement plus vert', 'Contribuons à un environnement plus vert ! Unis pour aider lance un projet de plantation d''arbres pour promouvoir la durabilité et la préservation de l''environnement.', 1);
INSERT INTO Actualites (aid, date_actualite, intitule, image, amorce, actualite, visible) VALUES (11, '2023-12-21', 'Atelier de formation à l''emploi pour les personnes en situation de précarité', 'images/iconeArticle/iconeArticle.png', 'Atelier de formation à l''emploi pour les personnes en situation de précarité', 'Unis pour aider organise un atelier de formation à l''emploi pour aider les personnes en situation de précarité à acquérir de nouvelles compétences et à trouver un emploi.', 1);
