-- Base SQLite locale, données de démonstration du projet scolaire.
CREATE TABLE Actualites (aid INTEGER PRIMARY KEY AUTOINCREMENT, date_actualite TEXT NOT NULL, intitule TEXT NOT NULL, image TEXT NOT NULL, amorce TEXT NOT NULL, actualite TEXT NOT NULL, visible INTEGER NOT NULL DEFAULT 1);
CREATE TABLE Departements (did INTEGER PRIMARY KEY, departement TEXT NOT NULL);
CREATE TABLE Personnel (pid INTEGER PRIMARY KEY, prenom TEXT NOT NULL, nom TEXT NOT NULL, courriel TEXT NOT NULL, mdp TEXT NOT NULL, telephone TEXT NOT NULL, photo TEXT, description TEXT, IdDepartement INTEGER REFERENCES Departements(did) ON DELETE SET NULL, isAdmin INTEGER DEFAULT 0);
CREATE TABLE Utilisateurs (user_id INTEGER PRIMARY KEY, username TEXT NOT NULL, password TEXT NOT NULL, personnel_id INTEGER REFERENCES Personnel(pid));
